L7_1.m_Bounce = L8_1
L7_1.m_Talk_KOREA = "자주 해봤거든요. 양동이 물 안 쏟고 달리기 같은 거."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "よくやってたんです。バケツの水をこぼさずに走ったり。"
L7_1.m_Talk_ENG = "I've done it often. You know, like, running with a bucket of water and trying not to spill it."
L7_1.m_Talk_TWN = "這種事我經常做喔，比如說挑水的時候不讓水灑出來。"
L7_1.m_Talk_SCN = "这种事我经常做哦，比如说挑水的时候不让水洒出来。"
L7_1.m_Talk_DEU = "I've done it often. You know, like, running with a bucket of water and trying not to spill it."
L7_1.m_Talk_FRA = "I've done it often. You know, like, running with a bucket of water and trying not to spill it."
L8_1 = {}
L8_1.m_CutScenKey_Talk = "EP12_ACT4_EPILOGUE@8#Talk"
L8_1.m_CutScenProcessKey = 8
L8_1.m_CutScenID = 576
L8_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L8_1.m_bWaitClick = true
