L8_1.m_CharStrID = "ROOKIE_GRONIA_NULL_NULL"
L8_1.m_Pos = "C"
L8_1.m_Talk_KOREA = "생각보다 엄청 달렸네요. 직경이 6km나 되는 방해 역장이라니."
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "思ったより遠くまで来ましたね。直径が6kmもある力場だったなんて。"
L8_1.m_Talk_ENG = "Come to think of it, we ran pretty far. Didn't think the stasis field would have a diameter of 6 km."
L8_1.m_Talk_TWN = "比我想像中的還要遠啊……直徑竟然會有足足6公里……"
L8_1.m_Talk_SCN = "比我想象中的还要远啊……直径竟然会有足足6公里……"
L8_1.m_Talk_DEU = "Come to think of it, we ran pretty far. Didn't think the stasis field would have a diameter of 6 km."
L8_1.m_Talk_FRA = "Come to think of it, we ran pretty far. Didn't think the stasis field would have a diameter of 6 km."
L9_1 = {}
