L9_1.m_Pos = "C"
L9_1.m_Talk_KOREA = "게다가 역장을 가동시킨 기물이 보이지 않으니, 부술 수도 없겠어요."
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "それに、力場を稼働した器物がどこにあるかもわからないから、壊すこともできなさそう。"
L9_1.m_Talk_ENG = "Also, I haven't spotted the object that activated it, so I can't even destroy it."
