L9_1.m_Talk_SCN = "而且我看不到发生力场的装置，没办法破坏……"
L9_1.m_Talk_DEU = "Also, I haven't spotted the object that activated it, so I can't even destroy it."
L9_1.m_Talk_FRA = "Also, I haven't spotted the object that activated it, so I can't even destroy it."
L10_1 = {}
