L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 576
L20_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "세상을 구해야 할 자네가… 고작 한 사람을 지키려다 사경을 헤매는 꼴이라니."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "世界を救うべき君が……たかが1人の人間を守ろうとして生死を彷徨っているなんて。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "You should be saving the world... but you're on the brink of dying, just to save one person."
