L21_1 = "你本應是要拯救這個世界的……現在卻為了保護一個人而徘徊在死亡的邊緣。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "你本应是要拯救这个世界的……现在却为了保护一个人而徘徊在死亡的边缘。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "You should be saving the world... but you're on the brink of dying, just to save one person."
