L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 73
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 576
L23_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L24_1 = "우린 모두, 여기까지 오면서 많은 빚을 졌지."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "私たちは皆、ここに来るまで多くの借りを作った。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "We all owed a lot to be here."
L23_1.m_Talk_ENG = L24_1
L24_1 = "我們所有人，走到這裡都欠下了很多債。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "我们所有人，走到这里都欠下了很多债。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "We all owed a lot to be here."
L23_1.m_Talk_DEU = L24_1
L24_1 = "We all owed a lot to be here."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "EP12_ACT4_EPILOGUE@74#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 74
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 576
L24_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L25_1 = "많은 이들의 희생이 없었다면, 오늘 이 순간에 이르지도 못했을 거야."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "大勢の犠牲なしでは、今この瞬間も存在しない。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Without the sacrifices of many people, we would not have even reached this point."
L24_1.m_Talk_ENG = L25_1
L25_1 = "如果沒有許多人的犧牲，我們也無法到達今天這一刻。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "如果没有许多人的牺牲，我们也无法到达今天这一刻。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Without the sacrifices of many people, we would not have even reached this point."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Without the sacrifices of many people, we would not have even reached this point."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "EP12_ACT4_EPILOGUE@75#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 75
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 576
L25_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L26_1 = "그런데, 그 모든 희생을 종용해온 나 같은 사람이… 총탄 한 발 맞는 걸 두려워 해서야 쓰나."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "その犠牲を彼らに押しつけてきた私のような人間が……銃に撃たれることを恐れてはいけないだろう。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "But, for a person who has been urging all those sacrifices... How can I be scared of being hit by a single bullet?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "所以，像我這樣一直要求大家犧牲的人……怎麼能害怕一顆子彈呢……"
L25_1.m_Talk_TWN = L26_1
L26_1 = "所以，像我这样一直要求大家牺牲的人……怎么能害怕一颗子弹呢……"
L25_1.m_Talk_SCN = L26_1
L26_1 = "But, for a person who has been urging all those sacrifices... How can I be scared of being hit by a single bullet?"
L25_1.m_Talk_DEU = L26_1
L26_1 = "But, for a person who has been urging all those sacrifices... How can I be scared of being hit by a single bullet?"
L25_1.m_Talk_FRA = L26_1
