L28_1 = "EP12_ACT4_EPILOGUE@77#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 77
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 576
L27_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "착각하고 있군. 파블린의 선택은 자네를 위한 게 아니었어."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "勘違いするな。パブリンは君のためにあのような選択をしたわけではない。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "You are mistaken. Pavlin's choice wasn't for you."
L27_1.m_Talk_ENG = L28_1
L28_1 = "你搞錯了，帕芙琳的選擇並不是為了你。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "你搞错了。帕芙琳的选择并不是为了你。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "You are mistaken. Pavlin's choice wasn't for you."
L27_1.m_Talk_DEU = L28_1
L28_1 = "You are mistaken. Pavlin's choice wasn't for you."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "EP12_ACT4_EPILOGUE@78#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 78
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 576
L28_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "세계의 미래, 모두가 멸망을 피해 살아남을 수 있는 미래를 위한 대의이자 숭고한 희생이지."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "あれは世界の未来、人類が滅亡から逃れ生き延びる未来のための大儀であり、崇高なる犠牲だ。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "It was a noble sacrifice for a greater cause. For a future where the world and everyone with it avoids destruction."
L28_1.m_Talk_ENG = L29_1
L29_1 = "她為的是世界的未來，為了所有人都能夠逃避滅亡而存活的未來。這是偉大的事業，也是崇高的犧牲。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "她为的是世界的未来，为了所有人都能够逃避灭亡而存活的未来。这是伟大的事业，也是崇高的牺牲。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "It was a noble sacrifice for a greater cause. For a future where the world and everyone with it avoids destruction."
L28_1.m_Talk_DEU = L29_1
L29_1 = "It was a noble sacrifice for a greater cause. For a future where the world and everyone with it avoids destruction."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "EP12_ACT4_EPILOGUE@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 576
L29_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "그걸 자네가 진 빚이라 생각하고 매번 죽음으로 갚아내려 한다면, 목숨이 몇 개라도 남아나지 않을 걸세."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "それを借りだと思い、毎回死で償おうとするのなら、命がいくつあっても足りないだろう。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "If you think of that as the debt you owe and try to repay it with death every time, then you will need more lives than you can count."
L29_1.m_Talk_ENG = L30_1
L30_1 = "如果你每次都想著用生命來償還那筆債的話，不管有幾條命都不夠用的。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "如果你每次都想着用生命来偿还那笔债的话，不管有几条命都不够用的。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "If you think of that as the debt you owe and try to repay it with death every time, then you will need more lives than you can count."
L29_1.m_Talk_DEU = L30_1
L30_1 = "If you think of that as the debt you owe and try to repay it with death every time, then you will need more lives than you can count."
L29_1.m_Talk_FRA = L30_1
