L33_1 = "EP12_ACT4_EPILOGUE@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 576
L32_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L32_1.m_bWaitClick = true
