L33_1 = "THEMA_CS_ORCHESTRA"
L32_1.m_StartBGMFileName = L33_1
L32_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L33_1 = "하지만 그럼에도… 그 모든 기로의 중심에 서서, 업을 짊어지기로 했잖나."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "だが、それでもなお……そのすべての岐路の中心に立ち、すべての業を背負うと決めたではないか。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "But still... I've decided to be at the center of it all and carry the burden."
L32_1.m_Talk_ENG = L33_1
L33_1 = "但即便如此……我還是決定站在所有岔路的中心，背負起這一切。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "但即便如此……我还是决定站在所有岔路的中心，背负起这一切。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "But still... I've decided to be at the center of it all and carry the burden."
L32_1.m_Talk_DEU = L33_1
L33_1 = "But still... I've decided to be at the center of it all and carry the burden."
