L36_1 = "EP12_ACT4_EPILOGUE@85#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 576
L35_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "그 충동 한 번 때문에 지금까지의 희생이 무로 돌아간다 해도, 그따위 변명을 댈 셈인가?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "一度の衝動で、今までの犠牲がすべて無に還ることになっても、そんな言い訳をするつもりか？"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Will you continue to make excuses even when all the sacrifices you've made thus far become meaningless due to a single impulsive decision?"
L35_1.m_Talk_ENG = L36_1
L36_1 = "就因為那一次衝動，至今為止所有的犧牲都將化為烏有，你打算用那種蹩腳藉口來搪塞嗎？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "就因为那一次冲动，至今为止所有的牺牲都将化为乌有，你打算用那种蹩脚借口来搪塞吗？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Will you continue to make excuses even when all the sacrifices you've made thus far become meaningless due to a single impulsive decision?"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Will you continue to make excuses even when all the sacrifices you've made thus far become meaningless due to a single impulsive decision?"
L35_1.m_Talk_FRA = L36_1
