L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 88
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 576
L38_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L39_1 = "정말로 내가 사라진다고 해서… 인류에 희망이 영원히 사라질까?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "私が消えたとして……人類の希望が永遠に消えると思うか？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Will humanity's hope really be lost forever... because I'm gone?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "真的會因為我消失了……人類的未來就永遠沒有希望了嗎？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "真的会因为我消失了……人类的未来就永远没有希望了吗？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Will humanity's hope really be lost forever... because I'm gone?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Will humanity's hope really be lost forever... because I'm gone?"
