L41_1 = "EP12_ACT4_EPILOGUE@90#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 90
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 576
L40_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L41_1 = "옛 세계에 버려진 테라브레인이 현실에 이르러 인과율에 영향을 주기 시작한 건, 내 계획이 아니었네."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "旧世界に捨てられたテラブレインが現実の因果律に影響を及ぼしたのは、私の想定外だった。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "It wasn't my plan when a Terrabrain abandoned in the old world reached the Normalside and started affecting causality."
L40_1.m_Talk_ENG = L41_1
L41_1 = "被遺棄在舊世界的特拉大腦來到現世並影響了因果關係，這並不在我的計畫之內。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "被遗弃在旧世界的特拉大脑来到现实并影响了因果率，这并不在我的计划之内。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "It wasn't my plan when a Terrabrain abandoned in the old world reached the Normalside and started affecting causality."
L40_1.m_Talk_DEU = L41_1
L41_1 = "It wasn't my plan when a Terrabrain abandoned in the old world reached the Normalside and started affecting causality."
L40_1.m_Talk_FRA = L41_1
