L43_1 = "EP12_ACT4_EPILOGUE@92#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 92
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 576
L42_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L43_1 = "모든 걸 잃는 실패를 겪고도 몇몇 관리국 전대가 우리에게 다시 돌아온 건, 누군가의 계획이 아닌 그들의 신념 덕분이었지."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "すべてを失う失敗を経験しても管理局戦隊が帰って来たのは、誰かの計画のおかげではない。彼らの信念のおかげだ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Despite experiencing failures of losing everything, the reason several of the Administration's divisions came back to us is not anyone's plan, but their belief."
L42_1.m_Talk_ENG = L43_1
L43_1 = "即使經歷了失去一切的失敗，仍有一些管理局的前隊員回到了我們身邊，這並不是因為某個人的計畫，而是因為他們自己的信念。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "即使经历了失去一切的失败，仍有一些管理局的前队员回到了我们身边，这并不是因为某个人的计划，而是因为他们自己的信念。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Despite experiencing failures of losing everything, the reason several of the Administration's divisions came back to us is not anyone's plan, but their belief."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Despite experiencing failures of losing everything, the reason several of the Administration's divisions came back to us is not anyone's plan, but their belief."
L42_1.m_Talk_FRA = L43_1
