L45_1 = 94
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 576
L44_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L45_1 = "발키리의 운명을 되찾겠다는 우리의 무모한 계획을… 태어날 예정조차 없던 그 아이가 도와줄 거라, 누가 기대라도 했었나?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "ヴァルキリーの運命を取り戻すという私たちの無謀な計画を……生まれる予定すらなかったあの子が助けてくれると誰が予想できただろう？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Our reckless plan to reclaim Valkyrie's fate... Who would have expected that a child who was never to be born would help that cause?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "而我們那個找回女武神命運的魯莽的計畫……誰又能想到，最終是那個本不該出生的孩子來幫忙了呢？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "而我们那个找回女武神命运的鲁莽的计划……谁又能想到，最终是那个本不该出生的孩子来帮忙了呢？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Our reckless plan to reclaim Valkyrie's fate... Who would have expected that a child who was never to be born would help that cause?"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Our reckless plan to reclaim Valkyrie's fate... Who would have expected that a child who was never to be born would help that cause?"
L44_1.m_Talk_FRA = L45_1
