L2_1 = "반복되는 세계가 조금씩 변화하며 그 굴레를 벗어나고 있는 건, 단 한 사람의 노력 때문이 아니야."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "繰り返される世界が少しずつ変化し、その軌道から離れられたのは、1人の努力のおかげではない。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "It wasn't just one person's effort that made this repetitive world gradually change and break free from the cycle."
L1_1.m_Talk_ENG = L2_1
L2_1 = "不斷變化的世界逐漸擺脫束縛，並不是因為一個人的努力。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "不断变化的世界逐渐摆脱束缚，并不是因为一个人的努力。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "It wasn't just one person's effort that made this repetitive world gradually change and break free from the cycle."
L1_1.m_Talk_DEU = L2_1
L2_1 = "It wasn't just one person's effort that made this repetitive world gradually change and break free from the cycle."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "EP12_ACT4_EPILOGUE@102#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 102
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 576
L2_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L3_1 = "모든 원인은 운명을 벗어나고자 하는 본성…"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "すべての原因は、運命から逃れようとする本能……"
L2_1.m_Talk_JPN = L3_1
L3_1 = "The cause of it all is the nature of wanting to escape fate..."
L2_1.m_Talk_ENG = L3_1
L3_1 = "這一切的原因都是我們想要掙脫命運的本性……"
L2_1.m_Talk_TWN = L3_1
L3_1 = "这一切的原因都是我们想要挣脱命运的本性……"
L2_1.m_Talk_SCN = L3_1
L3_1 = "The cause of it all is the nature of wanting to escape fate..."
L2_1.m_Talk_DEU = L3_1
L3_1 = "The cause of it all is the nature of wanting to escape fate..."
L2_1.m_Talk_FRA = L3_1
