L4_1 = 103
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 576
L3_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L4_1 = "감정을 갖고 사고하는 모든 존재가 가진 공통의 성질이지."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "感情を持ち思考するすべての存在に備わった、共通の性質だ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "A common trait possessed by all emotional and intelligent beings."
L3_1.m_Talk_ENG = L4_1
L4_1 = "這是所有擁有情感和思考能力的存在所共有的特質。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "这是所有拥有情感和思考能力的存在所共有的特质。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "A common trait possessed by all emotional and intelligent beings."
L3_1.m_Talk_DEU = L4_1
L4_1 = "A common trait possessed by all emotional and intelligent beings."
L3_1.m_Talk_FRA = L4_1
