L4_1.m_CutScenID = 576
L4_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L5_1 = "난 그저 그들이 나아갈 방향을 제시할 뿐, 한 번도 그들보다 특별한 존재였던 적은 없네."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "私は彼らに方向を示すだけ、1度たりとも彼らより特別な存在だったことはない。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "I merely provide the direction they should take. I've never been more special than any of them."
L4_1.m_Talk_ENG = L5_1
L5_1 = "我只是為他們指引了方向，從未覺得自己比他們特別。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "我只是为他们指引了方向，从未觉得自己比他们特别。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "I merely provide the direction they should take. I've never been more special than any of them."
L4_1.m_Talk_DEU = L5_1
L5_1 = "I merely provide the direction they should take. I've never been more special than any of them."
L4_1.m_Talk_FRA = L5_1
