L9_1 = "그래서, 이젠 모든 걸 내버려두고 떠나도 괜찮다는 건가?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "だから、もうすべてを手放し消え去ってもいいと？"
L8_1.m_Talk_JPN = L9_1
L9_1 = "So, you are content with leaving everything behind?"
L8_1.m_Talk_ENG = L9_1
L9_1 = "所以，你現在是想放下一切離開了嗎？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "所以，你现在是想放下一切离开了吗？"
