L11_1 = "EP12_ACT4_EPILOGUE@110#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 110
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 576
L10_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L11_1 = "관리 종료를 선언한 시점에서… 내가 안배할 수 있는 모든 준비는 사실상 끝났어."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "管理終了を宣言した時点で……私が干渉できるすべての準備は事実上終わったのだ。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "From the moment the Administration Complete was declared... all the preparations I could've arranged were virtually done."
L10_1.m_Talk_ENG = L11_1
L11_1 = "在宣佈管理結束的那一刻……我能安排的一切準備實際上都已經完成了。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "在宣布管理结束的那一刻……我能安排的一切准备实际上都已经完成了。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "From the moment the Administration Complete was declared... all the preparations I could've arranged were virtually done."
L10_1.m_Talk_DEU = L11_1
L11_1 = "From the moment the Administration Complete was declared... all the preparations I could've arranged were virtually done."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "EP12_ACT4_EPILOGUE@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 576
L11_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L12_1 = "그건, 과거의 굴레를 벗어난 새 시작을 의미하기도 하지만… 내게 주어진 역할의 끝을 의미하기도 하지."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "それは過去のしがらみを抜け出した、新たな始まりを意味するが……同時に、私に与えられた役目の終わりを告げることでもある。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Although it means a new beginning, free from the shackles of the past... it also means the end of my given role."
L11_1.m_Talk_ENG = L12_1
L12_1 = "那不僅就表示擺脫過去的枷鎖，迎來新的開始……也就表示我所承擔的角色即將結束。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "那不仅意味着摆脱过去的枷锁，迎来新的开始……也意味着我所承担的角色即将结束。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Although it means a new beginning, free from the shackles of the past... it also means the end of my given role."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Although it means a new beginning, free from the shackles of the past... it also means the end of my given role."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
