L12_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L13_1 = "아직 해야 할 일들이 산더미처럼 쌓여 눈에 아른대긴 해도…"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "まだやるべきことはいくつかあるが……"
L12_1.m_Talk_JPN = L13_1
L13_1 = "There are still piles of work that must be completed, lingering in my head..."
L12_1.m_Talk_ENG = L13_1
L13_1 = "雖然還有堆積成山的事情等著我們去做……"
L12_1.m_Talk_TWN = L13_1
L13_1 = "虽然还有堆积成山的事情等着我们去做……"
L12_1.m_Talk_SCN = L13_1
L13_1 = "There are still piles of work that must be completed, lingering in my head..."
L12_1.m_Talk_DEU = L13_1
L13_1 = "There are still piles of work that must be completed, lingering in my head..."
L12_1.m_Talk_FRA = L13_1
