L14_1 = "내가 아니면 해낼 수 없을 거란 불안함은… 별로 들지 않는군."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "自分じゃないと成せない……という不安は感じない。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I don't feel any anxiety... that I'd be the only one who could do it."
L13_1.m_Talk_ENG = L14_1
L14_1 = "但如果不是一定要我來的話……我也並不會因此而感到不安。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "但如果不是非得要我来的话……我也并不会因此而感到不安。"
