L24_1 = "늑대는 신의 목숨을 노릴만큼 강해졌지만, 신의 허를 찌를 만큼 영리하진 못해."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "オオカミは神の命を狙えるほど強くなったけど、神の隙を突けるほど賢くはない。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "The Wolf might have gotten strong enough to end a god, but she isn't clever enough to outthink one."
L23_1.m_Talk_ENG = L24_1
L24_1 = "狼已經強大到可以覬覦神的生命，但還沒有聰明到能夠擊中神的要害。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "狼已经强大到可以觊觎神的生命，但还没有聪明到能够击中神的要害。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "The Wolf might have gotten strong enough to end a god, but she isn't clever enough to outthink one."
L23_1.m_Talk_DEU = L24_1
L24_1 = "The Wolf might have gotten strong enough to end a god, but she isn't clever enough to outthink one."
