L25_1 = "敵對者雖然決心刺穿了魔王的背，但終究還是個無法擺脫師父教導的菜鳥。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "敌对者虽然决心刺穿了魔王的后背，但终究还是个无法摆脱师父教导的菜鸟。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "The Antagonist might be resolute enough to stab the Demon Lord in the back, but he is still a rookie who hasn't left his master's embrace yet."
