L42_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L43_1 = "글쎄… 탐미엘 본인이라기엔 너무 인정 넘치는 발언이란 생각이 들더군."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "さあ……タミエルにしては情に満ちた発言だと思ってね。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Well... I just thought that Tammiel wouldn't speak to me so compassionately like that."
L42_1.m_Talk_ENG = L43_1
L43_1 = "嗯……我覺得這話太有人情味了，不像是塔米爾本人會說的。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "嗯……我觉得这话太有人情味了，不像是塔米尔本人会说的。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Well... I just thought that Tammiel wouldn't speak to me so compassionately like that."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Well... I just thought that Tammiel wouldn't speak to me so compassionately like that."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP12_ACT4_EPILOGUE@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 576
L43_1.m_CutScenStrID = "EP12_ACT4_EPILOGUE"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L44_1 = "포기를 종용하긴커녕 오히려 삶에 의지를 불어넣을 정도로 날 자극하다니. 그녀답지 않잖나."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "諦めを促すどころか、生への意志を吹き込むように私を刺激するなんて……彼女らしくないだろう。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "It's not like her to try and provoke me to keep living. She would encourage me to give up."
L43_1.m_Talk_ENG = L44_1
L44_1 = "不僅沒有慫恿我放棄，反而刺激了我，讓我重新燃起了活下去的意志。這不像她。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "不仅没有怂恿我放弃，反而刺激了我，让我重新燃起了活下去的意志。这不像她。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "It's not like her to try and provoke me to keep living. She would encourage me to give up."
L43_1.m_Talk_DEU = L44_1
L44_1 = "It's not like her to try and provoke me to keep living. She would encourage me to give up."
L43_1.m_Talk_FRA = L44_1
