L46_1 = "자극하려던 건 맞지만, 거짓말은 안 했어."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "刺激しようとしたのは事実だけど、嘘はついてない。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I was trying to provoke you, but I wasn't lying."
L45_1.m_Talk_ENG = L46_1
L46_1 = "雖然是想激你沒錯，但我也沒說謊。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "虽然是想激你没错，但我也没说谎。"
