L46_1.m_Pos = "C"
L47_1 = "이제 죽어도 된다는 맘 편한 소릴 할 거면, 당장 눈앞의 불부터 꺼야지. 안 그래?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "もう死んでもいいなんてのんきなことが言えるぐらいなら、目の前の火事から消してよ。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "If you're going to tell us that you're okay with dying, shouldn't you at least take care of the urgent problems right in front of you first?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "如果你現在想安心去死了，那也至少把眼前自己挑起的火給滅了。不是嗎？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "如果你现在想安心去死了，那也至少把眼前自己挑起的火给灭了。不是吗？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "If you're going to tell us that you're okay with dying, shouldn't you at least take care of the urgent problems right in front of you first?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "If you're going to tell us that you're okay with dying, shouldn't you at least take care of the urgent problems right in front of you first?"
