L25_1 = "하지만 그 육체의 한계는 명확하죠. 당신과 부딪힐 때마다 힘이 약해지는 게 느껴지거든요."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "しかしその肉体には確かに限界がある。あなたとぶつかるたびに、力が弱まっていることを感じます。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "But that body must have a limit. I can feel you are getting weaker every time we clash."
L24_1.m_Talk_ENG = L25_1
L25_1 = "但是那具身體的極限是明確的。每次與你碰撞時，我都能感覺到力量在減弱。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "但是那具身体的极限是明确的。每次与你碰撞时，我都能感觉到力量在减弱。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "But that body must have a limit. I can feel you are getting weaker every time we clash."
L24_1.m_Talk_DEU = L25_1
L25_1 = "But that body must have a limit. I can feel you are getting weaker every time we clash."
L24_1.m_Talk_FRA = L25_1
