L42_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L43_1 = "자네 무기만큼은 아니지만, 이것도 맞으면 제법 아픈 총일세."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "君の武器ほどではないが、この銃も撃たれるとかなり痛いやつさ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "This gun might not be as powerful as yours, but it will hurt."
L42_1.m_Talk_ENG = L43_1
L43_1 = "雖然比不上你的武器，但被這把槍打中也會很痛的喔。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "虽然比不上你的武器，但被这把枪打中也会很疼的哦。"
