L44_1 = "...Oh, my. It would have been better for you if you had not moved at all."
L43_1.m_Talk_ENG = L44_1
L44_1 = "……哎呀，你最好還是別輕舉妄動。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "……哎呀。您最好还是别轻举妄动。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "...Oh, my. It would have been better for you if you had not moved at all."
L43_1.m_Talk_DEU = L44_1
L44_1 = "...Oh, my. It would have been better for you if you had not moved at all."
L43_1.m_Talk_FRA = L44_1
