L50_1 = "…멋지네요. 압도적인 무력 차 앞에서도 전혀 주눅들지 않는 그 태도."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "……素敵ですね。圧倒的な力の差を目にしてもなお怯まないその姿。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "...I admire your attitude of not being intimidated in the face of this stark difference in power."
L49_1.m_Talk_ENG = L50_1
L50_1 = "……真是了不起啊。即使面對壓倒性的武力差距，也完全沒有畏縮的態度。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "……真是了不起啊。即使面对压倒性的武力差距，也完全没有畏缩的态度。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "...I admire your attitude of not being intimidated in the face of this stark difference in power."
L49_1.m_Talk_DEU = L50_1
L50_1 = "...I admire your attitude of not being intimidated in the face of this stark difference in power."
L49_1.m_Talk_FRA = L50_1
