L31_1 = "무사한 건 아니지. 딱 죽지 않을 만큼 응급처치만 해뒀을 뿐이니까."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "無事とは言えないな。ギリギリ死なない程度に、応急手当をしただけだから。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Not really fine. He's only received first aid just enough to keep him from dying."
L30_1.m_Talk_ENG = L31_1
L31_1 = "要是我就不會用這個詞。我只是做了緊急處理，確保他不會死而已。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "要是我就不会用这个词。我只是做了紧急处理，确保他不会死而已。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Not really fine. He's only received first aid just enough to keep him from dying."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Not really fine. He's only received first aid just enough to keep him from dying."
