L32_1 = "돌아가 제대로 된 치료를 받지 않으면 당장이라도 목숨이 위태로워질 거다."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "帰ってちゃんと治療してもらわないと、命が危うい。"
