L32_1 = "If he doesn't get proper treatment after we go back, his condition will get worse."
L31_1.m_Talk_ENG = L32_1
L32_1 = "回去還得接受治療，否則他的生命隨時都還會有危險。"
L31_1.m_Talk_TWN = L32_1
